book = {}
while True:
    parts = input().split()
    cmd = parts[0]
    if cmd == "end":
        break
    elif cmd == "add":
        book[parts[1]] = parts[2]
    elif cmd == "find":
        print(book.get(parts[1], "없음"))
    elif cmd == "del":
        if parts[1] in book:
            del book[parts[1]]
            print("삭제됨")
        else:
            print("없음")
